/* Déclic — Anglais A2 (unités 10 à 12). Format : docs/ANGLAIS.md */
(()=>{
// Toutes les combinaisons de morceaux de phrase (variantes acceptées pour une réponse écrite)
const X=(...ps)=>ps.reduce((acc,p)=>acc.flatMap(a=>[].concat(p).map(b=>(a+' '+b).trim())),['']).map(s=>s.replace(/\s+/g,' '));
COURS.push(
{subj:'en', sem:'a2', id:'en-a2-rules', o:10, h:'Rules', p:'Comprendre un règlement, dire ce qui est obligatoire, interdit ou permis, et demander quelque chose poliment : <i lang="en">must, mustn’t, have to, can, could</i>.', steps:[
 {kind:'Écoute', h:'À l’auberge de jeunesse',
  p:`<p>À la fin de cette unité, tu sauras comprendre un règlement, dire ce qui est obligatoire, interdit ou permis, et demander quelque chose poliment en anglais.</p>
<p>Jess arrive dans une auberge de jeunesse à Édimbourg. La réceptionniste lui explique le règlement. <b>Écoute sans lire</b>, deux fois si tu veux, puis réponds.</p>
<p><b>Question :</b> qu’est-ce que Jess n’a pas le droit de faire&nbsp;?</p>`,
  audio:[['Receptionist','Hi, welcome to the Castle Hostel! Can I see your passport, please?'],['Jess','Sure, here you are. Are there any rules I need to know?'],['Receptionist','Just a few. You must be quiet after eleven at night, and you mustn’t smoke in the building.'],['Jess','OK. Do I have to leave my key at reception when I go out?'],['Receptionist','No, you don’t have to. You can keep it with you. But you have to check out before ten on Sunday.'],['Jess','Fine. Can I use the kitchen?'],['Receptionist','Yes, of course. You can cook until ten p.m. Oh, and could you sign here, please?'],['Jess','There you go. Could I leave my bike in the garden?'],['Receptionist','I’m afraid you can’t, but you can put it in the garage.']], cache:true,
  opts:['Garder sa clé quand elle sort','Fumer dans le bâtiment','Cuisiner à neuf heures du soir','Ranger son vélo dans le garage'], ans:1,
  why:'<i lang="en">You mustn’t smoke in the building</i> : fumer est interdit. En revanche, elle peut garder sa clé (elle <i lang="en">doesn’t have to</i> la laisser), cuisiner jusqu’à 22 heures et mettre son vélo au garage, mais pas dans le jardin.'},

 {kind:'Vocabulaire', h:'Règles et panneaux',
  p:`<p>Voici les expressions pour dire ce qui est obligatoire, interdit ou permis, et quelques panneaux qu’on voit partout dans les pays anglophones. Touche une ligne pour l’entendre, puis répète-la à voix haute.</p>`,
  mots:[['You must…','Tu dois… (obligation)','You must be quiet after eleven.'],['You mustn’t…','Tu ne dois pas… (c’est interdit)','You mustn’t smoke in the building.'],['You have to…','Tu dois… (c’est la règle)','You have to check out before ten.'],['You don’t have to…','Tu n’es pas obligé de…','You don’t have to leave your key.'],['You can… / You’re allowed to…','Tu as le droit de…','You can keep your key.'],['You can’t… / You aren’t allowed to…','Tu n’as pas le droit de…','You can’t park here.'],['a rule','une règle','Are there any rules I need to know?'],['a sign','un panneau','What does that sign say?'],['a fine','une amende','You’ll get a fine if you park here.'],['No smoking','Défense de fumer'],['Keep off the grass','Pelouse interdite'],['Staff only','Réservé au personnel'],['to switch off your phone','éteindre son téléphone','Please switch off your phone.'],['to wear a helmet','porter un casque','You have to wear a helmet on the building site.']],
  note:'<b>Sur les panneaux</b>, l’anglais est très bref : <i lang="en">No</i> + nom ou verbe en <i>-ing</i> (<i lang="en">No parking, No dogs</i>), ou un impératif (<i lang="en">Keep left</i>, <i lang="en">Mind the gap</i> : attention à l’espace entre le train et le quai, dans le métro de Londres). Les toilettes publiques s’appellent <i lang="en">toilets</i> en britannique et <i lang="en">restrooms</i> en américain.'},

 {kind:'Vocabulaire', h:'Demander poliment',
  p:`<p>Pour demander la permission ou un service, quelques formules suffisent dans presque toutes les situations : à l’hôtel, au bureau, chez des amis. Touche chaque ligne pour l’entendre.</p>`,
  mots:[['Can I…?','Est-ce que je peux… ?','Can I use the kitchen?'],['Could I…?','Est-ce que je pourrais… ? (plus poli)','Could I leave my bike here?'],['May I…?','Puis-je… ? (formel)','May I come in?'],['Could you…, please?','Pourriez-vous…, s’il vous plaît ?','Could you sign here, please?'],['Is it OK if I…?','Ça te dérange si je… ?','Is it OK if I open the window?'],['to borrow','emprunter','Could I borrow your pen?'],['to lend','prêter','Could you lend me your pen?'],['Sure. / Of course.','Bien sûr.'],['Go ahead.','Vas-y, je t’en prie.','Can I sit here? – Go ahead.'],['I’m afraid…','Je suis désolé, mais… (refus poli)','I’m afraid you can’t.'],['Here you are.','Tiens, voilà (en tendant un objet)','Your passport? Here you are.']],
  note:'<b>Piège :</b> <i lang="en">borrow</i> = emprunter (je prends), <i lang="en">lend</i> = prêter (je donne). On dit <i lang="en">Could I borrow your pen?</i> ou <i lang="en">Could you lend me your pen?</i>, mais jamais <s>Could you borrow me your pen?</s>'},

 {kind:'Pratique', h:'À toi : un panneau',
  p:'Tu prépares les panneaux d’un bureau. Sur une porte, seuls les employés ont le droit d’entrer. <b>Question :</b> que dit le panneau « Réservé au personnel » en anglais&nbsp;?', lab:'Le panneau', txt:['Staff only','Employees only','Staff members only','Private: staff only'],
  why:'<i lang="en">Staff only</i> : <i lang="en">staff</i> = le personnel, <i lang="en">only</i> = seulement. Sur le même modèle : <i lang="en">Members only</i> (réservé aux membres).'},

 {kind:'Grammaire', h:'Must et have to : l’obligation',
  p:`<p>La réceptionniste dit <i lang="en">You <b>must</b> be quiet after eleven</i> et <i lang="en">You <b>have to</b> check out before ten.</i> Les deux phrases expriment une obligation. Quelle est la différence&nbsp;?</p>
<div class="def"><p><b>must + verbe de base</b> : <i lang="en">I must go. She must wear a uniform.</i> C’est un modal, comme <i lang="en">can</i> : même forme à toutes les personnes, pas de <i>-s</i>, pas de <i>do</i>.</p><p><b>have to + verbe de base</b> : <i lang="en">I have to go. She <b>has</b> to work on Saturdays. <b>Do</b> you have to wear a tie?</i> C’est un verbe ordinaire : il prend <i>-s</i> à la 3e personne et <i>do / does</i> dans les questions et à la négation.</p></div>
<div class="idea"><p>À l’oral, <b>have to</b> est bien plus fréquent : il parle d’une obligation qui vient de l’extérieur (la loi, le patron, l’horaire). <b>must</b> exprime plutôt une obligation que <b>celui qui parle</b> ressent ou impose (<i lang="en">I must call my mum</i> : il faut vraiment que j’appelle ma mère), et on le lit souvent dans les règlements écrits (<i lang="en">Passengers must show their tickets</i>). Dans beaucoup de phrases, les deux sont possibles.</p></div>
<div class="ex"><p><i lang="en">In the UK, you have to drive on the left.</i> (c’est la loi)<br><i lang="en">I must remember her birthday this year!</i> (je me le dis à moi-même)<br><i lang="en">Yesterday I <b>had to</b> work late.</i> (<i>must</i> n’a pas de passé : on utilise <i>had to</i>)</p></div>
<div class="warn"><p>Les pièges des francophones : pas de <i>to</i> après <i>must</i> (<s>I must to go</s>), pas de <i>-s</i> (<s>he musts</s>), pas de <i>do</i> (<s>Do you must…?</s>). Et pour le passé ou le futur, seul <i>have to</i> fonctionne : <i lang="en">I had to, I’ll have to</i>.</p></div>`,
  audio:'You must be quiet after eleven. You have to check out before ten. She has to work on Saturdays. Yesterday I had to work late.'},

 {kind:'Grammaire', h:'Mustn’t ou don’t have to : le grand piège',
  p:`<p>Jess demande si elle doit laisser sa clé. Réponse : <i lang="en">No, you <b>don’t have to</b>.</i> Et pour la cigarette : <i lang="en">You <b>mustn’t</b> smoke.</i> À l’affirmatif, <i>must</i> et <i>have to</i> se ressemblent ; à la négation, ils disent deux choses <b>très différentes</b>.</p>
<div class="def"><p><b>mustn’t</b> (<i>must not</i>) = c’est <b>interdit</b>, il ne faut pas. <i lang="en">You mustn’t park here.</i><br><b>don’t have to</b> (<i>doesn’t have to</i>) = ce n’est <b>pas obligatoire</b>, pas besoin, mais on peut. <i lang="en">You don’t have to pay: it’s free.</i></p></div>
<div class="idea"><p>Pense à une porte : avec <i>mustn’t</i>, la porte est fermée à clé ; avec <i>don’t have to</i>, la porte est ouverte et tu choisis. Pour une interdiction, l’oral préfère souvent <b>can’t</b> : <i lang="en">You can’t smoke here.</i> Et pour une permission, <b>can</b> : <i lang="en">You can keep your key.</i></p></div>
<div class="ex"><p><i lang="en">It’s Sunday: I don’t have to get up early.</i> (je peux rester au lit, ou pas)<br><i lang="en">You mustn’t tell anyone. It’s a secret!</i> (interdit d’en parler)<br><i lang="en">Students don’t have to wear a uniform, but they can’t wear caps in class.</i></p></div>
<div class="warn"><p>« Tu ne dois pas » veut dire « c’est interdit » : <i>mustn’t</i>. Mais « tu n’es pas obligé » se traduit par <b>don’t have to</b>, jamais par <i>mustn’t</i>. Si tu dis <s>You mustn’t come to the party</s> pour « tu n’es pas obligé de venir », tu interdis à ton ami de venir&nbsp;!</p></div>`,
  audio:'You mustn’t park here. You don’t have to pay: it’s free. You can’t smoke here. You can keep your key.'},

 {kind:'Méthode', h:'Choisir le bon verbe pour une règle',
  p:`<p><b>Quand :</b> chaque fois que tu expliques une règle ou que tu lis un règlement. <b>Pourquoi ça marche :</b> chaque verbe correspond à une seule situation ; si tu identifies d’abord la situation, le verbe vient tout seul. <b>Comment :</b> demande-toi si l’action est obligatoire, interdite, permise ou pas nécessaire.</p>
<ul><li>Obligatoire → <b>must</b> ou <b>have to</b> (<b>has to</b> à la 3e personne).</li><li>Interdit → <b>mustn’t</b> ou <b>can’t</b>.</li><li>Permis → <b>can</b>.</li><li>Pas nécessaire → <b>don’t have to</b> (<b>doesn’t have to</b>).</li><li>Puis le verbe à la forme de base, sans <i>to</i> (sauf dans <i>have to</i>).</li></ul>`,
  demo:{enonce:'Traduis le règlement d’une piscine : « Il faut prendre une douche avant de nager. Il est interdit de courir. Le bonnet n’est pas obligatoire. Les enfants peuvent utiliser le toboggan. »',
   etapes:[{f:'Obligatoire : <i lang="en">You must have a shower before you swim.</i>',w:'C’est une obligation écrite dans un règlement : <i>must</i> (ou <i>have to</i>). <i lang="en">have a shower</i> en britannique, <i lang="en">take a shower</i> en américain.'},
    {f:'Interdit : <i lang="en">You mustn’t run.</i> ou <i lang="en">You can’t run.</i>',w:'Une interdiction : <i>mustn’t</i>, ou <i>can’t</i>, plus courant à l’oral.'},
    {f:'Pas nécessaire : <i lang="en">You don’t have to wear a swimming cap.</i>',w:'Le bonnet est facultatif. Surtout pas <i>mustn’t</i>, qui l’interdirait.'},
    {f:'Permis : <i lang="en">Children can use the water slide.</i>',w:'Une permission : <i>can</i> + verbe de base.'}],
   conclusion:'<i lang="en">You must have a shower before you swim. You mustn’t run. You don’t have to wear a swimming cap. Children can use the water slide.</i>'}},

 {kind:'Pratique', h:'À toi : une interdiction',
  p:'Au bord de la piscine, un panneau interdit de plonger. Explique la règle à un ami anglais. <b>Question :</b> comment dis-tu « Tu ne dois pas plonger ici. »&nbsp;? (<i lang="en">to dive</i> = plonger)', lab:'Ta phrase',
  txt:['You mustn’t dive here.',...X(['You mustn’t','You can’t','You aren’t allowed to'],['dive'],['here','in here'])],
  why:'C’est une interdiction : <i lang="en">You mustn’t dive here</i>, ou à l’oral <i lang="en">You can’t dive here</i>. <i lang="en">You don’t have to dive</i> voudrait dire « tu n’es pas obligé de plonger ».'},

 {kind:'Pratique', h:'À toi : pas obligé',
  p:'Ton ami croit qu’il faut payer pour entrer au British Museum, à Londres. En fait, l’entrée est gratuite. <b>Question :</b> écris en anglais « Tu n’es pas obligé de payer. »', lab:'Ta phrase',
  txt:['You don’t have to pay.',...X(['You don’t have to pay','You don’t need to pay','You needn’t pay'],['','anything','it’s free','it is free'])],
  why:'Absence d’obligation : <i lang="en">You don’t have to pay</i> (ou <i lang="en">You don’t need to pay</i>). <i lang="en">You mustn’t pay</i> voudrait dire qu’il est interdit de payer.'},

 {kind:'Pratique', h:'À toi : poser la question',
  p:'Tu réserves une visite guidée par téléphone. Touche les mots dans le bon ordre. <b>Question :</b> comment demandes-tu « Est-ce qu’on doit payer à l’avance&nbsp;? »',
  ordre:['Do','we','have to','pay','in advance?'],
  why:'<i lang="en">Do we have to pay in advance?</i> <i>have to</i> est un verbe ordinaire : la question se forme avec <i>do</i>. <i lang="en">Must we pay…?</i> existe, mais sonne très formel.'},

 {kind:'Grammaire', h:'Demander une permission ou un service',
  p:`<p>Dans le dialogue, Jess demande <i lang="en">Can I use the kitchen?</i> et <i lang="en">Could I leave my bike in the garden?</i> ; la réceptionniste, elle, demande <i lang="en">Could you sign here, please?</i> Ce sont deux sortes de demandes, avec les mêmes petits verbes.</p>
<div class="def"><p><b>Demander la permission</b> (c’est moi qui fais l’action) : <b>Can I…? Could I…? May I…?</b> + verbe de base.<br><b>Demander un service</b> (c’est l’autre qui fait l’action) : <b>Can you…? Could you…?</b> + verbe de base, avec <i>please</i>.</p></div>
<div class="idea"><p>Plus la phrase est indirecte, plus elle est polie. <i>Can</i> va très bien entre amis ; <i>Could</i> est plus poli, pour un inconnu, un client, un chef ; <i>May I</i> est formel (<i lang="en">May I come in?</i>). Ici, <i>could</i> n’est pas un passé : c’est l’équivalent de notre conditionnel « pourriez-vous ». Pour accepter : <i lang="en">Sure. Of course. Go ahead.</i> Pour refuser poliment, on adoucit : <i lang="en">I’m afraid you can’t. Sorry, I’m afraid not.</i></p></div>
<div class="ex"><p><i lang="en">Can I sit here? – Sure, go ahead.</i><br><i lang="en">Could you open the window, please? – Of course.</i><br><i lang="en">Could I pay by card? – I’m afraid not, only cash.</i></p></div>
<div class="warn"><p>Pas de <i>do</i> ni de <i>to</i> : <s>Do I can…?</s>, <s>Could you to help me?</s> On ne répond pas <s>Yes, you could</s> : on dit <i lang="en">Yes, of course</i> ou <i lang="en">Yes, you can</i>. Et un simple impératif (<i lang="en">Give me the salt.</i>) paraît très sec en anglais, même avec <i>please</i> : préfère <i lang="en">Could you pass the salt, please?</i></p></div>`,
  audio:[['Jess','Can I sit here?'],['Tom','Sure, go ahead.'],['Jess','Could you pass the salt, please?'],['Tom','Of course. Here you are.']]},

 {kind:'Méthode', h:'Transformer un ordre en demande polie',
  p:`<p><b>Quand :</b> dès que tu veux que quelqu’un fasse quelque chose pour toi, ou que tu veux faire quelque chose chez les autres. <b>Pourquoi ça marche :</b> l’anglais adoucit les demandes en les transformant en question avec un modal ; c’est la forme attendue, même entre collègues. <b>Comment :</b></p>
<ol><li>Qui fait l’action ? Moi → <b>Can / Could I</b> ; l’autre → <b>Can / Could you</b>.</li><li>À qui je parle ? Un ami → <i>Can</i> ; un inconnu, un client, un chef → <i>Could</i>.</li><li>Ajoute le verbe de base et son complément.</li><li>Termine par <b>please</b> (ou place-le après le sujet : <i lang="en">Could you please…?</i>).</li></ol>`,
  demo:{enonce:'Au restaurant, tu veux l’addition. Ta première idée : <i lang="en">Give me the bill.</i> Rends la demande polie, puis demande si tu peux payer par carte.',
   etapes:[{f:'Qui agit ? Le serveur apporte l’addition : <i lang="en">Could you…</i>',w:'C’est l’autre qui fait l’action, et c’est un inconnu : <i>Could you</i>.'},
    {f:'<i lang="en">Could you bring me the bill, please?</i>',w:'Verbe de base <i>bring</i>, complément, puis <i>please</i>. (<i>bill</i> en britannique, <i>check</i> en américain.)'},
    {f:'Payer par carte : c’est moi qui agis → <i lang="en">Could I pay by card, please?</i>',w:'Je demande une permission : <i>Could I</i> + verbe de base.'}],
   conclusion:'<i lang="en">Could you bring me the bill, please? Could I pay by card?</i> Réponses possibles : <i lang="en">Of course</i>, ou <i lang="en">I’m afraid we only take cash</i>.'}},

 {kind:'Pratique', h:'À toi : demander un service',
  p:'Un collègue anglais parle trop vite pour toi. <b>Question :</b> écris en anglais « Pourriez-vous parler plus lentement, s’il vous plaît&nbsp;? »', lab:'Ta question',
  txt:['Could you speak more slowly, please?',...X(['Could you','Could you please','Can you','Can you please','Would you'],['speak','talk'],['more slowly','a bit more slowly','a little more slowly','slower'],['','please'])],
  why:'C’est l’autre qui agit, et la situation demande de la politesse : <i lang="en">Could you speak more slowly, please?</i> Pas de <i>to</i> après <i>could</i>.'},

 {kind:'Pratique', h:'À toi : emprunter',
  p:'Tu as oublié ton stylo. Ta voisine de bureau en a un. <b>Question :</b> demande-lui poliment si tu peux emprunter son stylo.', lab:'Ta question',
  txt:['Could I borrow your pen, please?',...X(['Could I','Can I','May I','Could I please','Is it OK if I'],['borrow your pen'],['','please']),...X(['Could you','Can you','Could you please'],['lend me your pen'],['','please'])],
  why:'C’est toi qui prends : <i lang="en">Could I borrow your pen, please?</i> Ou, en mettant l’autre en sujet : <i lang="en">Could you lend me your pen?</i>'},

 {kind:'Prononciation', h:'Can, can’t, must : les formes faibles',
  p:`<p>Beaucoup de francophones n’entendent pas la différence entre <i>can</i> et <i>can’t</i>, parce que le <i>t</i> final est souvent à peine prononcé. Le vrai indice est ailleurs : la <b>voyelle</b> et l’<b>accent</b>.</p>
<div class="def"><ul><li><b>can</b> dans une phrase affirmative est faible et court : « k’n ». <i lang="en">You k’n park here.</i></li><li><b>can’t</b> est toujours fort, avec une voyelle longue en britannique : « kaant ». <i lang="en">You <b>can’t</b> park here.</i> (En américain, la voyelle est celle de <i>cat</i>.)</li><li>Dans une réponse courte, <i>can</i> redevient fort : <i lang="en">Yes, you <b>can</b>.</i></li><li><b>must</b> est faible dans la phrase : « m’st ». <b>mustn’t</b> se dit « mass’nt » : le premier <i>t</i> ne se prononce pas.</li></ul></div>
<div class="warn"><p>Si tu prononces <i>can</i> fort et long, ton interlocuteur risque de comprendre <i>can’t</i>. Pour être compris, affaiblis <i>can</i> et accentue <i>can’t</i>.</p></div>`,
  audio:'You can park here. You can’t park here. You must be quiet. You mustn’t smoke. Can I sit here? Yes, you can.'},

 {kind:'Écoute', h:'Can ou can’t ?',
  p:'Au musée, une guide explique les règles aux visiteurs. <b>Écoute sans lire</b>, en faisant attention à <i lang="en">can</i> et <i lang="en">can’t</i>. <b>Question :</b> qu’est-ce qui est permis dans la deuxième salle&nbsp;?',
  audio:'Welcome to the museum. In the first room, you can take photos, but you can’t use a flash. In the second room, you can’t take any photos, but you can sit down and draw the paintings. And please remember: you mustn’t touch anything.', cache:true,
  opts:['Prendre des photos sans flash','Dessiner les tableaux','Toucher les sculptures','Prendre des photos avec flash'], ans:1,
  why:'<i lang="en">In the second room, you can’t take any photos, but you can sit down and draw the paintings</i> : pas de photos, mais on peut dessiner. Les photos sans flash, c’est dans la première salle.'},

 {kind:'Lecture', h:'Le règlement d’une colocation',
  p:`<p>Tu vas emménager dans une colocation à Manchester. Lis le règlement affiché dans la cuisine, puis réponds. Tu peux aussi l’écouter.</p>
<div class="blk" data-t="House rules"><p lang="en">Welcome to 14 Oak Street! Please read our house rules carefully.<br>1. Rent: you have to pay the rent on the first day of every month.<br>2. Kitchen: you can use your own shelf in the fridge, but you mustn’t take other people’s food without asking. Wash your dishes the same day.<br>3. Noise: you must be quiet after 11 p.m. on weekdays. At weekends you can stay up later, but please keep the music down.<br>4. Guests: friends can stay for two nights. You don’t have to ask the others, but you have to tell them.<br>5. Cleaning: everyone has to clean the bathroom once a month. Check the list on the door.<br>6. Smoking: you can’t smoke inside the house, but you can smoke in the garden.<br>Any questions? Just ask Mike in room 3. Enjoy living here!</p></div>
<p><b>Question :</b> un ami vient dormir deux nuits chez toi. Que dois-tu faire&nbsp;?</p>`,
  audio:'Welcome to 14 Oak Street! Please read our house rules carefully. One. Rent: you have to pay the rent on the first day of every month. Two. Kitchen: you can use your own shelf in the fridge, but you mustn’t take other people’s food without asking. Wash your dishes the same day. Three. Noise: you must be quiet after 11 p.m. on weekdays. At weekends you can stay up later, but please keep the music down. Four. Guests: friends can stay for two nights. You don’t have to ask the others, but you have to tell them. Five. Cleaning: everyone has to clean the bathroom once a month. Check the list on the door. Six. Smoking: you can’t smoke inside the house, but you can smoke in the garden. Any questions? Just ask Mike in room 3. Enjoy living here!',
  opts:['Demander la permission à tous les colocataires','Simplement prévenir les autres','Payer un supplément de loyer','Rien du tout'], ans:1,
  why:'<i lang="en">You don’t have to ask the others, but you have to tell them</i> : pas besoin de demander la permission, mais il faut prévenir. Encore une fois, <i>don’t have to</i> = pas obligé.'},

 {kind:'Dictée', h:'Dictée : où se garer',
  p:'Écoute et écris exactement la phrase. Tu peux réécouter autant que tu veux, et utiliser « Plus lentement ».',
  dictee:'You mustn’t park here, but you can park behind the station.',
  why:'Vérifie l’apostrophe de <i lang="en">mustn’t</i> (le premier <i>t</i> ne s’entend pas, mais il s’écrit) et la virgule devant <i lang="en">but</i>.'},

 {kind:'Oral', h:'Répète après le modèle',
  p:`<p>Écoute la phrase, puis dis-la à voix haute en touchant « Dire la phrase ». Les mots importants sont forts, les petits mots sont faibles et rapides : <i lang="en">Could you <b>help</b> me with my <b>bags</b>, <b>please</b>?</i> La voix monte un peu à la fin, ce qui rend la demande aimable.</p>`,
  dire:'Could you help me with my bags, please?',
  note:'Si un mot reste en rouge, réécoute la phrase lentement, puis recommence. <i lang="en">Could you</i> se prononce presque « coud-jou ».'},

 {kind:'Oral', h:'Les règles de ton quotidien',
  p:`<p>Parle pendant 30 à 60 secondes des règles de ton travail, de ton école ou de ta maison. Donne au moins deux obligations, une interdiction, une chose qui n’est pas obligatoire et une permission. Touche « Parler », puis « J’ai fini ».</p>`,
  oral:{modele:'At my office, we have quite a lot of rules. We have to start work at half past eight, and we must wear a badge all the time. We mustn’t eat at our desks, so we go to the kitchen for lunch. We don’t have to wear a suit: jeans are fine. And on Fridays, we can work from home. I think the rules are fair.',
   criteres:['J’ai donné au moins deux obligations avec must ou have to','J’ai donné une interdiction avec mustn’t ou can’t','J’ai dit ce qui n’est pas obligatoire avec don’t have to','J’ai donné une permission avec can','J’ai mis has to (avec -s) à la 3e personne si j’ai parlé de quelqu’un d’autre']}},

 {kind:'Écriture', h:'Un message pour ton invité',
  p:'Tu prêtes ton appartement à un ami anglophone pendant tes vacances. Laisse-lui un message (au moins 50 mots) : deux obligations, une interdiction, une chose qu’il n’est pas obligé de faire, une permission, et une demande polie avec <i lang="en">Could you…?</i>',
  ecrire:{min:50, modele:'Hi Josh, welcome to my flat! Here are a few rules. You have to water the plants every two days, and you must lock the door when you go out. You mustn’t open the bathroom window because it’s broken. You don’t have to clean everything before you leave. You can use my bike and you can eat anything in the fridge. Could you feed the cat in the morning, please? Thanks a lot and enjoy your stay! Léa',
   criteres:[{t:'J’ai exprimé une obligation (must, have to)', re:'\\b(must|have to|has to)\\b'},{t:'J’ai exprimé une interdiction (mustn’t, can’t)', re:'\\b(mustn[’\']t|must not|can[’\']t|cannot|not allowed)\\b'},{t:'J’ai dit ce qui n’est pas obligatoire (don’t have to)', re:'\\b(don[’\']t|do not|doesn[’\']t|does not) (have|need) to\\b'},{t:'J’ai donné une permission (you can)', re:'\\byou can\\b'},{t:'J’ai fait une demande polie (Could you…? Can you…?)', re:'\\b(could|can) you\\b[^.!]*\\?'},'Je n’ai pas mis to après must, can ou could']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>Obligation : <b>must</b> + base (règle écrite, obligation que je ressens) ; <b>have to / has to</b> (obligation extérieure, le plus courant à l’oral). Au passé : <b>had to</b>.</li><li>Interdiction : <b>mustn’t</b> ou <b>can’t</b>. Absence d’obligation : <b>don’t / doesn’t have to</b>. Ne jamais confondre <i>mustn’t</i> (interdit) et <i>don’t have to</i> (pas obligé).</li><li>Permission : <b>can</b>. <i lang="en">You can keep your key.</i></li><li>Demander la permission : <i lang="en">Can I…? Could I…? May I…?</i> Demander un service : <i lang="en">Can you…? Could you…, please?</i> Répondre : <i lang="en">Sure. Of course. Go ahead. I’m afraid not.</i></li><li>Avec <i>must, can, could, may</i> : pas de <i>to</i>, pas de <i>-s</i>, pas de <i>do</i>. <i>have to</i> se conjugue comme un verbe ordinaire : <i lang="en">Does she have to…?</i></li><li>Panneaux : <i lang="en">No smoking, Keep off the grass, Staff only</i>. <i>borrow</i> = emprunter, <i>lend</i> = prêter.</li><li>Prononciation : <i>can</i> faible « k’n », <i>can’t</i> long et fort, <i>mustn’t</i> sans le premier <i>t</i>.</li></ul></div>`},

 {kind:'Mission', h:'Au contrôle de sécurité',
  p:'Tu prends l’avion à l’aéroport de Londres. Au contrôle de sécurité, un agent parle à un passager juste devant toi. Écoute le dialogue, puis réponds aux questions une par une. Tu peux réécouter à tout moment.',
  audio:[['Officer','Good morning. Have you got any liquids in your bag?'],['Passenger','Just a bottle of water.'],['Officer','I’m afraid you can’t take it through. You have to drink it or throw it away.'],['Passenger','Oh, OK. Do I have to take my laptop out?'],['Officer','Yes, you do. Put it in a separate tray, please. But you don’t have to take your shoes off.'],['Passenger','Great. Can I keep my jacket on?'],['Officer','No, sorry. Jackets must go in the tray too. Could you walk through here, please?']], cache:true,
  parts:[
   {q:'a) Que doit faire le passager avec sa bouteille d’eau&nbsp;?', opts:['La mettre dans un sac en plastique','La boire ou la jeter','La poser dans le bac','La laisser à l’agent'], ans:1, hint:'Écoute la phrase qui commence par <i lang="en">You have to…</i>', why:'<i lang="en">You have to drink it or throw it away</i> : la boire ou la jeter.'},
   {q:'b) Quelle phrase est vraie&nbsp;?', opts:['Il doit enlever ses chaussures.','Il peut garder sa veste.','Il n’est pas obligé d’enlever ses chaussures.','Il n’a pas le droit de prendre son ordinateur.'], ans:2, hint:'Attention au sens de <i lang="en">don’t have to</i>.', why:'<i lang="en">You don’t have to take your shoes off</i> : pas obligé de les enlever. La veste, elle, doit aller dans le bac (<i lang="en">must go in the tray</i>).'},
   {q:'c) Le passager voyage avec sa fille. Écris sa question en anglais : « Est-ce qu’elle doit aussi sortir sa tablette&nbsp;? »', lab:'Ta question', txt:['Does she have to take her tablet out too?',...X(['Does she have to','Does she also have to'],['take her tablet out','take out her tablet'],['','too','as well'])], hint:'<i>have to</i> se conjugue comme un verbe ordinaire : question avec <i>does</i> à la 3e personne.', why:'<i lang="en">Does she have to take her tablet out too?</i> <i>does</i> porte la 3e personne, donc <i>have</i> reste sans <i>-s</i>.'},
   {q:'d) Il te manque un bac. Demande poliment à l’agent : « Est-ce que je pourrais avoir un autre bac, s’il vous plaît&nbsp;? »', lab:'Ta question', txt:['Could I have another tray, please?',...X(['Could I have','Can I have','May I have','Could I get','Can I get','Could you give me','Can you give me','Could you please give me'],['another tray'],['','please'])], hint:'Tu demandes pour toi : <i lang="en">Could I…</i>', why:'<i lang="en">Could I have another tray, please?</i> (ou <i lang="en">Could you give me another tray?</i>). <i>Could</i> est la forme polie qui convient avec un inconnu.'}],
  sol:'<p lang="en">Officer: Good morning. Have you got any liquids in your bag? – Just a bottle of water. – I’m afraid you can’t take it through. You have to drink it or throw it away. – Oh, OK. Do I have to take my laptop out? – Yes, you do. Put it in a separate tray, please. But you don’t have to take your shoes off. – Great. Can I keep my jacket on? – No, sorry. Jackets must go in the tray too. Could you walk through here, please?</p><p>Le passager doit boire ou jeter son eau, sortir son ordinateur et mettre sa veste dans le bac, mais il n’est pas obligé d’enlever ses chaussures. Question à la 3e personne : <i lang="en">Does she have to…?</i> Demande polie : <i lang="en">Could I have another tray, please?</i></p>'},

 {kind:'Mission', h:'Un appartement de vacances',
  p:`<p>Tu as loué un appartement à Brighton pour une semaine. La propriétaire t’envoie ce message. Lis-le, puis réponds.</p>
<div class="blk" data-t="Message"><p lang="en">Hi Camille, welcome to Brighton! Here’s some information about the flat. Check-in is from 3 p.m., and on the day you leave, you have to put the keys in the key box by 11 a.m. Please remember that you mustn’t smoke inside the flat, and parties aren’t allowed. You don’t have to clean the flat before you leave, but please take the rubbish out: the bins are behind the building. You can use the two bikes in the garden, but you have to bring them back before dark. If you need anything, you can call me. Enjoy your stay! Sarah</p></div>`,
  parts:[
   {q:'a) Camille veut fêter son anniversaire avec dix amis dans l’appartement. Est-ce possible&nbsp;?', opts:['Oui, si elle nettoie après','Non, les fêtes sont interdites','Oui, mais pas après 23 heures','Oui, mais seulement dans le jardin'], ans:1, hint:'Cherche le mot <i lang="en">parties</i>.', why:'<i lang="en">Parties aren’t allowed</i> : les fêtes sont interdites. <i>not allowed</i> = interdit, comme <i>mustn’t</i>.'},
   {q:'b) Que doit-elle faire le jour du départ&nbsp;?', opts:['Nettoyer tout l’appartement','Appeler Sarah avant 11 heures','Mettre les clés dans la boîte avant 11 heures et sortir les poubelles','Rendre les vélos à Sarah'], ans:2, hint:'Distingue <i lang="en">you have to</i> et <i lang="en">you don’t have to</i>.', why:'<i lang="en">You have to put the keys in the key box by 11 a.m.</i>, et Sarah demande de sortir les poubelles. Le ménage n’est pas obligatoire (<i lang="en">You don’t have to clean</i>).'},
   {q:'c) Ton train arrive à 13 heures. Écris à Sarah une demande polie : « Est-ce que je pourrais arriver à une heure&nbsp;? »', lab:'Ta question', txt:['Could I arrive at one?',...X(['Could I','Can I','May I','Is it OK if I','Could I please'],['arrive','check in','come'],['at one','at one o’clock','at 1','at 1 p.m.','at 1 pm','at 1pm'],['','please'])], hint:'C’est toi qui agis : <i lang="en">Could I</i> + verbe de base.', why:'<i lang="en">Could I arrive at one?</i> (ou <i lang="en">Could I check in at one?</i>). <i>Could I</i> est poli sans être trop formel.'},
   {q:'d) Explique la règle à ton amie qui t’accompagne : « Tu n’es pas obligée de nettoyer l’appartement, mais tu dois sortir les poubelles. »', lab:'Ta phrase', txt:['You don’t have to clean the flat, but you have to take the rubbish out.',...X(['You don’t have to','You don’t need to'],['clean the flat','clean the apartment'],['but'],['you have to','you must'],['take the rubbish out','take out the rubbish','take the trash out','take out the trash'])], hint:'Une absence d’obligation, puis une obligation.', why:'<i lang="en">You don’t have to clean the flat, but you have to take the rubbish out.</i> Ici, <i>mustn’t clean</i> serait faux : le ménage n’est pas interdit.'}],
  sol:'<p>Les fêtes sont interdites (<i lang="en">parties aren’t allowed</i>). Le jour du départ, Camille doit mettre les clés dans la boîte avant 11 heures et sortir les poubelles, mais elle n’est pas obligée de faire le ménage. Pour arriver plus tôt : <i lang="en">Could I arrive at one?</i> Pour expliquer la règle : <i lang="en">You don’t have to clean the flat, but you have to take the rubbish out.</i></p>'},
]},

{subj:'en', sem:'a2', id:'en-a2-people', o:11, h:'People', p:'Décrire le physique et le caractère de quelqu’un, préciser de qui on parle avec <i lang="en">who, which, that, where</i>, et parler des relations avec quelques phrasal verbs.', steps:[
 {kind:'Écoute', h:'Une photo de mariage',
  p:`<p>À la fin de cette unité, tu sauras décrire une personne, son physique et son caractère, préciser de qui tu parles et raconter tes relations avec les autres.</p>
<p>Maya montre à son ami Leo une photo du mariage de son frère. <b>Écoute sans lire</b>, puis réponds.</p>
<p><b>Question :</b> quelle phrase est vraie&nbsp;?</p>`,
  audio:[['Maya','Look, this is the photo that my mum took at my brother’s wedding.'],['Leo','Nice! Who’s the tall man who’s wearing glasses?'],['Maya','That’s my uncle Dave. He’s the one who looked after me when my parents were at work.'],['Leo','He looks really kind. And the woman with long curly hair?'],['Maya','That’s my cousin Sarah. She lives in the village where we grew up. We get on really well.'],['Leo','She looks like you!'],['Maya','Everyone says that. But she isn’t like me at all. She’s calm and sensible, and I’m a bit crazy.'],['Leo','And the little boy who’s eating cake?'],['Maya','Oh, that’s Sam. He’s the boy who lost the rings!']], cache:true,
  opts:['Dave est le petit garçon qui a perdu les alliances.','Sarah ressemble physiquement à Maya, mais elle a un autre caractère.','Maya et sa cousine ne s’entendent pas bien.','Dave est le frère de Maya.'], ans:1,
  why:'<i lang="en">She looks like you!</i> (elle te ressemble), mais <i lang="en">she isn’t like me at all</i> : son caractère est très différent, calme et raisonnable. Dave est l’oncle, Sam le garçon qui a perdu les alliances, et Maya s’entend très bien avec Sarah (<i lang="en">We get on really well</i>).'},

 {kind:'Vocabulaire', h:'Décrire l’apparence',
  p:`<p>Pour décrire le physique de quelqu’un, on parle surtout de sa taille, de ses cheveux, de son âge approximatif et de ce qu’il porte. Touche une ligne pour l’entendre, puis répète-la.</p>`,
  mots:[['tall / short','grand / petit (taille)','My uncle is very tall.'],['slim','mince','She’s tall and slim.'],['long / short hair','les cheveux longs / courts','He has short hair.'],['curly / straight hair','les cheveux bouclés / raides','Sarah has long curly hair.'],['fair / dark hair','les cheveux blonds / bruns','My brother has fair hair.'],['a beard / a moustache','une barbe / une moustache','He’s got a grey beard.'],['to wear glasses','porter des lunettes','The man who’s wearing glasses is my uncle.'],['in his thirties','dans la trentaine','She’s in her thirties.'],['What does he look like?','À quoi ressemble-t-il ? (le physique)','What does your new boss look like?']],
  note:'<b>hair</b> est indénombrable quand il s’agit de la chevelure : <i lang="en">She has long hair</i>, jamais <s>long hairs</s> ni <s>the hair long</s>. L’ordre est fixe : <b>longueur, forme, couleur + hair</b> : <i lang="en">long curly dark hair</i>. Pour les yeux : <i lang="en">She has blue eyes.</i>'},

 {kind:'Vocabulaire', h:'Le caractère',
  p:`<p>Pour le caractère, apprends les adjectifs par paires ou avec leur contraire : c’est plus facile à retenir. Attention à deux faux amis célèbres.</p>`,
  mots:[['friendly','sympathique, aimable','Our neighbours are very friendly.'],['kind','gentil','It’s very kind of you.'],['shy','timide','He’s shy with people he doesn’t know.'],['funny','drôle','My cousin is really funny.'],['easy-going','facile à vivre','My flatmate is very easy-going.'],['hard-working','travailleur','She’s the most hard-working person in the team.'],['reliable','fiable, sur qui on peut compter','He always arrives on time: he’s very reliable.'],['sensible','raisonnable (faux ami)','Sarah is calm and sensible.'],['sensitive','sensible, susceptible','Be careful what you say: he’s very sensitive.'],['What is she like?','Comment est-elle ? (le caractère)','What’s your new teacher like?']],
  note:'<b>Faux amis</b> : <i lang="en">sensible</i> = raisonnable, et « sensible » se dit <i lang="en">sensitive</i>. <i lang="en">sympathetic</i> veut dire compatissant, pas « sympa » : pour « sympa », dis <i lang="en">nice</i> ou <i lang="en">friendly</i>. Pour nuancer : <i lang="en">quite shy</i> (assez), <i lang="en">a bit lazy</i> (un peu, surtout pour un défaut), <i lang="en">really funny</i> (vraiment).'},

 {kind:'Pratique', h:'À toi : décrire quelqu’un',
  p:'Décris la cousine de Maya. <b>Question :</b> écris en anglais « Elle a les cheveux longs et bouclés et elle est très raisonnable. »', lab:'Ta phrase',
  txt:['She has long curly hair and she’s very sensible.',...X(['She has','She has got','She’s got'],['long curly hair','long, curly hair'],['and she is very sensible','and she’s very sensible','and is very sensible'])],
  why:'<i lang="en">She has long curly hair</i> : <i>hair</i> au singulier, adjectifs avant le nom (longueur puis forme). Et « raisonnable » = <i lang="en">sensible</i>, le faux ami.'},

 {kind:'Grammaire', h:'Look like ou be like : deux questions',
  p:`<p>Leo dit <i lang="en">She <b>looks like</b> you!</i> et Maya répond <i lang="en">she <b>isn’t like</b> me at all</i>. Ce n’est pas une contradiction : les deux expressions ne parlent pas de la même chose.</p>
<div class="def"><p><b>What does he/she look like?</b> = À quoi ressemble-t-il, elle ? → <b>le physique</b>. Réponse : <i lang="en">He’s tall and he has a beard.</i><br><b>What is he/she like?</b> = Comment est-il, elle ? → <b>le caractère</b>, ou une impression générale. Réponse : <i lang="en">She’s friendly and a bit shy.</i><br><b>look like + quelqu’un</b> = ressembler à quelqu’un : <i lang="en">You look like your dad.</i></p></div>
<div class="idea"><p>Dans <i>What is she like?</i>, <i>like</i> n’est pas le verbe « aimer » : c’est une préposition qui veut dire « comme ». Mot à mot : « Elle est comme quoi ? ». Et <i>look</i> parle de ce qu’on voit. Ces questions servent aussi pour les choses et les lieux : <i lang="en">What’s your new flat like? – It’s small but bright.</i></p></div>
<div class="ex"><p><i lang="en">What does your sister look like? – She’s short and she has dark hair.</i><br><i lang="en">What’s your sister like? – She’s funny and very generous.</i><br><i lang="en">He looks like a film star.</i> = Il ressemble à une star de cinéma.</p></div>
<div class="warn"><p>Les pièges des francophones : <s>What does she look?</s> (il manque <i>like</i>) ; <s>She looks like tired</s> (devant un adjectif, pas de <i>like</i> : <i lang="en">She looks tired</i>, elle a l’air fatiguée) ; et <s>Who does she like?</s> pour « à qui ressemble-t-elle » (ça veut dire « qui aime-t-elle ») : on dit <i lang="en">Who does she look like?</i></p></div>`,
  audio:'What does your sister look like? She’s short and she has dark hair. What’s your sister like? She’s funny and very generous.'},

 {kind:'Pratique', h:'À toi : la bonne question',
  p:'Ton amie a un nouveau collègue. Tu veux savoir s’il est sympa, drôle, travailleur… pas à quoi il ressemble. <b>Question :</b> écris en anglais « Comment est ton nouveau collègue&nbsp;? »', lab:'Ta question',
  txt:['What’s your new colleague like?',...X(['What is','What’s'],['your new colleague','your new co-worker','your new workmate'],['like'])],
  why:'Pour le caractère : <i lang="en">What’s your new colleague like?</i> <i lang="en">What does he look like?</i> porterait sur le physique.'},

 {kind:'Grammaire', h:'Who, which, that : préciser de qui on parle',
  p:`<p>Leo ne demande pas seulement « Qui est l’homme ? » : il y a plusieurs hommes sur la photo. Il précise : <i lang="en">the tall man <b>who’s wearing glasses</b></i>. Ce morceau de phrase, placé juste après le nom, dit <b>de quel homme</b> on parle. C’est une proposition relative.</p>
<div class="def"><p><b>who</b> pour une personne : <i lang="en">the man who lives next door</i>.<br><b>which</b> pour une chose ou un animal : <i lang="en">the bus which goes to the airport</i>.<br><b>that</b> pour les deux, très courant à l’oral : <i lang="en">the woman that I met, the photo that my mum took</i>.</p></div>
<div class="idea"><p>En français, on choisit entre « qui » et « que » selon la fonction (sujet ou complément). En anglais, on choisit selon <b>ce dont on parle</b> : une personne (<i>who</i>) ou une chose (<i>which</i>). <i lang="en">The man who called</i> (l’homme qui a appelé) et <i lang="en">the man who I called</i> (l’homme que j’ai appelé) utilisent le même <i>who</i>. Quand le pronom est complément (« que »), on peut même le supprimer : <i lang="en">the photo (that) my mum took</i>.</p></div>
<div class="ex"><p><i lang="en">Sam is the boy who lost the rings.</i><br><i lang="en">This is the phone which I bought last week.</i> = <i lang="en">This is the phone I bought last week.</i><br><i lang="en">I know a man that can repair old radios.</i></p></div>
<div class="warn"><p>Ne répète pas le sujet ou le complément : <s>the man who he lives next door</s>, <s>the phone which I bought it</s>. Le relatif remplace déjà <i>he</i> ou <i>it</i>. Et pas de <i>which</i> pour une personne : <s>my friend which lives in Paris</s>.</p></div>`,
  audio:'Sam is the boy who lost the rings. This is the phone which I bought last week. This is the phone I bought last week.'},

 {kind:'Grammaire', h:'Where : le lieu où',
  p:`<p>Maya dit <i lang="en">the village <b>where</b> we grew up</i> : le village où nous avons grandi. Pour un lieu, on utilise <b>where</b>.</p>
<div class="def"><p><b>un lieu + where + sujet + verbe</b> : <i lang="en">the café where we met, the town where I was born, the office where she works</i>.</p></div>
<div class="idea"><p><i>where</i> remplace « là, à cet endroit » de la deuxième phrase : <i lang="en">This is the café. We met <b>there</b>.</i> → <i lang="en">This is the café <b>where</b> we met.</i> On peut aussi utiliser <i>that</i> ou <i>which</i> et mettre la préposition à la fin : <i lang="en">the café (that) we met in</i>, très courant à l’oral.</p></div>
<div class="ex"><p><i lang="en">Lausanne is the city where I studied.</i><br><i lang="en">Do you know a shop where I can buy stamps?</i><br><i lang="en">That’s the hospital where my aunt works.</i></p></div>
<div class="warn"><p>Le français dit aussi « le jour <b>où</b> je l’ai rencontrée », mais pour un moment, l’anglais n’utilise pas <i>where</i> : <i lang="en">the day (that) I met her</i> ou <i lang="en">the day when I met her</i>. Et après <i>where</i>, on ne répète pas <i>there</i> : <s>the town where I live there</s>.</p></div>`,
  audio:'This is the café. We met there. This is the café where we met. That’s the hospital where my aunt works.'},

 {kind:'Méthode', h:'Relier deux phrases avec un relatif',
  p:`<p><b>Quand :</b> pour éviter deux phrases courtes qui parlent de la même personne ou de la même chose, ou pour préciser de qui on parle. <b>Pourquoi ça marche :</b> le pronom relatif remplace le mot répété et accroche la deuxième phrase au nom. <b>Comment :</b></p>
<ol><li>Repère le mot répété dans la deuxième phrase (<i>he, she, it, they, there</i>…).</li><li>Choisis le relatif : personne → <b>who</b> (ou <i>that</i>) ; chose → <b>which</b> (ou <i>that</i>) ; lieu → <b>where</b>.</li><li>Remplace le mot répété par le relatif, en tête de la deuxième phrase.</li><li>Place le tout <b>juste après le nom</b> dont on parle.</li></ol>`,
  demo:{enonce:'Relie les deux phrases : <i lang="en">I have a neighbour. She plays the drums at midnight.</i>',
   etapes:[{f:'Mot répété : <i lang="en">She</i> = <i lang="en">a neighbour</i>.',w:'C’est la même personne dans les deux phrases.'},
    {f:'Une personne → <i lang="en">who</i> (ou <i lang="en">that</i>).',w:'Pas <i>which</i>, réservé aux choses.'},
    {f:'<i lang="en">She plays the drums</i> → <i lang="en">who plays the drums</i>',w:'<i>who</i> remplace <i>she</i> : on ne garde pas les deux.'},
    {f:'<i lang="en">I have a neighbour who plays the drums at midnight.</i>',w:'La relative vient juste après <i>a neighbour</i>.'}],
   conclusion:'<i lang="en">I have a neighbour who plays the drums at midnight.</i> Même chose avec un lieu : <i lang="en">This is the park. I run there.</i> → <i lang="en">This is the park where I run.</i>'}},

 {kind:'Pratique', h:'À toi : une personne',
  p:'Relie les deux phrases avec un pronom relatif. <b>Question :</b> <i lang="en">I have a friend. He speaks five languages.</i>', lab:'Ta phrase',
  txt:['I have a friend who speaks five languages.',...X(['I have','I have got'],['a friend'],['who','that'],['speaks five languages'])],
  why:'<i>He</i> désigne une personne : <i lang="en">who</i> (ou <i lang="en">that</i>) le remplace. <i lang="en">I have a friend who speaks five languages.</i> Pas de <s>who he speaks</s>.'},

 {kind:'Pratique', h:'À toi : un lieu',
  p:'Relie les deux phrases. <b>Question :</b> <i lang="en">This is the restaurant. We had our first date there.</i>', lab:'Ta phrase',
  txt:['This is the restaurant where we had our first date.',...X(['This is the restaurant'],['that','which',''],['we had our first date in']),'This is the restaurant in which we had our first date.'],
  why:'<i>there</i> désigne un lieu : <i lang="en">where</i> le remplace. <i lang="en">This is the restaurant where we had our first date.</i> À l’oral, on entend aussi <i lang="en">the restaurant we had our first date in</i>.'},

 {kind:'Pratique', h:'À toi : une chose',
  p:'Tu renseignes un touriste à la gare. <b>Question :</b> écris en anglais « Le train qui va à Londres part à neuf heures. »', lab:'Ta phrase',
  txt:['The train which goes to London leaves at nine.',...X(['The train'],['which','that'],['goes to London'],['leaves','departs'],['at nine','at 9','at nine o’clock','at 9 o’clock','at 9 a.m.','at 9am','at nine a.m.'])],
  why:'Un train est une chose : <i lang="en">which</i> ou <i lang="en">that</i>. <i lang="en">The train which goes to London leaves at nine.</i> Attention au <i>-s</i> de <i>goes</i> et de <i>leaves</i> : le sujet est <i>the train</i>.'},

 {kind:'Vocabulaire', h:'Phrasal verbs : les relations',
  p:`<p>Un <b>phrasal verb</b> est un verbe suivi d’une petite particule (<i lang="en">up, after, on, out…</i>). Ensemble, ils prennent un sens nouveau, qu’on ne peut pas toujours deviner : <i lang="en">look</i> = regarder, mais <i lang="en">look after</i> = s’occuper de. Les anglophones les utilisent sans cesse à l’oral, souvent à la place d’un verbe plus formel (<i lang="en">look after</i> plutôt que <i lang="en">take care of</i>). Apprends-les comme des mots entiers, avec leur exemple.</p><p>Ceux-ci parlent de la famille et des relations. Touche chaque ligne pour l’entendre.</p>`,
  mots:[['to get on (well) with','bien s’entendre avec','I get on well with my sister.'],['to look after','s’occuper de, garder','My uncle looked after me when I was little.'],['to grow up','grandir','We grew up in the same village.'],['to bring up','élever (un enfant)','My grandparents brought me up.'],['to take after','tenir de (un parent)','She takes after her mother: they’re both very calm.'],['to fall out with','se brouiller avec','He fell out with his brother last year.'],['to look up to','admirer, prendre pour modèle','I’ve always looked up to my grandmother.']],
  note:'<b>Où mettre le complément ?</b> Avec <i lang="en">get on with, look after, take after, look up to, fall out with</i>, il vient toujours <b>après</b> la particule : <i lang="en">She looks after her grandmother. She looks after her.</i> <i lang="en">grow up</i> n’a pas de complément (<i lang="en">I grew up in Sion</i>). <i lang="en">bring up</i> est différent : un pronom se place au milieu (<i lang="en">They brought me up</i>). Et ne confonds pas <i lang="en">look after</i> (s’occuper de), <i lang="en">look for</i> (chercher) et <i lang="en">look at</i> (regarder).'},

 {kind:'Pratique', h:'À toi : un phrasal verb',
  p:'<b>Question :</b> écris en anglais « Je m’entends bien avec mon frère. »', lab:'Ta phrase',
  txt:['I get on well with my brother.',...X(['I get on well with','I get on with','I get on really well with','I get on very well with','I get along well with','I get along with'],['my brother'])],
  why:'<i lang="en">I get on well with my brother.</i> En américain, on dit plutôt <i lang="en">get along with</i>. Pas de <s>I understand me well with</s>, calque du français.'},

 {kind:'Pratique', h:'Remets la phrase dans l’ordre',
  p:'Touche les mots dans le bon ordre. <b>Question :</b> comment dit-on « C’est la femme qui s’occupait de mes enfants » ?',
  ordre:['That’s','the woman','who','looked after','my children.'],
  why:'<i lang="en">That’s the woman who looked after my children.</i> La relative (<i>who…</i>) suit directement <i>the woman</i>, et le complément vient après <i>look after</i>.'},

 {kind:'Prononciation', h:'Le h anglais : who, her, hair',
  p:`<p>En français, le <i>h</i> ne se prononce jamais. En anglais, il se prononce presque toujours : c’est un petit souffle, comme quand on embue une vitre. Les mots de cette unité en sont pleins : <i lang="en">who, he, her, hair, husband, happy, hard-working</i>.</p>
<div class="def"><ul><li>Le <b>h</b> se souffle : <i lang="en">hair</i> « hèr », <i lang="en">who</i> « hou ». Mets ta main devant ta bouche : tu dois sentir l’air.</li><li>Quelques mots ont un <i>h</i> muet : <i lang="en">hour, honest, honour</i>.</li><li>Dans <i lang="en">who, whose, whole</i>, on entend un <i>h</i> ; dans <i lang="en">what, where, which, why</i>, on entend un <i>w</i>.</li></ul></div>
<div class="warn"><p>Oublier le <i>h</i> change le sens : <i lang="en">hair</i> (cheveux) / <i lang="en">air</i> (air), <i lang="en">heat</i> (chaleur) / <i lang="en">eat</i> (manger), <i lang="en">hate</i> (détester) / <i lang="en">eight</i> (huit). L’erreur inverse existe aussi : ajouter un <i>h</i> devant une voyelle quand on se concentre trop (<s>h-I h-eat</s>).</p></div>`,
  audio:'Who’s that? He’s my husband, Harry. He has short hair and he’s very hard-working. Hair, air. Heat, eat. Hate, eight.'},

 {kind:'Oral', h:'Répète : le h',
  p:`<p>Écoute la phrase, puis dis-la à voix haute en touchant « Dire la phrase ». Souffle bien chaque <i>h</i> : <i lang="en"><b>H</b>elen’s <b>h</b>usband is the tall man <b>wh</b>o <b>h</b>as short <b>h</b>air.</i></p>`,
  dire:'Helen’s husband is the tall man who has short hair.',
  note:'Si la reconnaissance vocale comprend <i lang="en">air</i> au lieu de <i lang="en">hair</i>, ton <i>h</i> était trop faible : recommence en soufflant davantage.'},

 {kind:'Lecture', h:'La personne que j’admire',
  p:`<p>Lis ce texte écrit pour un concours de rédaction, puis réponds. Tu peux aussi l’écouter.</p>
<div class="blk" data-t="The person I look up to"><p lang="en">The person I look up to most is my grandmother, Rose. She grew up on a small farm in Wales, where she looked after her five younger brothers and sisters. She left school at fourteen, but she never stopped learning. When she was forty, she went to university and became a teacher.</p><p lang="en">Today she is eighty-two. She’s short and slim, with white curly hair and bright blue eyes. She’s kind and very funny, and she always has a story which makes everyone laugh. She’s also a bit stubborn: she still drives her old red car, which is older than my dad!</p><p lang="en">I take after her in some ways. Like her, I love books and I’m quite stubborn. We get on really well, and I visit her every Sunday. She’s the person who taught me that it’s never too late to learn.</p></div>
<p><b>Question :</b> quelle phrase est vraie à propos de Rose&nbsp;?</p>`,
  audio:'The person I look up to most is my grandmother, Rose. She grew up on a small farm in Wales, where she looked after her five younger brothers and sisters. She left school at fourteen, but she never stopped learning. When she was forty, she went to university and became a teacher. Today she is eighty-two. She’s short and slim, with white curly hair and bright blue eyes. She’s kind and very funny, and she always has a story which makes everyone laugh. She’s also a bit stubborn: she still drives her old red car, which is older than my dad! I take after her in some ways. Like her, I love books and I’m quite stubborn. We get on really well, and I visit her every Sunday. She’s the person who taught me that it’s never too late to learn.',
  opts:['Elle a quitté l’école à quatorze ans et n’a plus jamais étudié.','Elle est allée à l’université à quarante ans.','Elle est grande, avec des cheveux raides.','Elle ne conduit plus depuis longtemps.'], ans:1,
  why:'<i lang="en">When she was forty, she went to university and became a teacher.</i> Elle est petite et mince, avec des cheveux bouclés, et elle conduit toujours sa vieille voiture rouge. <i lang="en">stubborn</i> = têtu.'},

 {kind:'Dictée', h:'Dictée : un portrait',
  p:'Écoute et écris exactement les deux phrases. Tu peux réécouter autant que tu veux, et utiliser « Plus lentement ».',
  dictee:'My sister takes after our father. She is tall and very funny.',
  why:'Vérifie le <i>-s</i> de <i lang="en">takes</i> (3e personne) et l’orthographe de <i lang="en">father</i> et <i lang="en">funny</i> (deux n).'},

 {kind:'Oral', h:'Quelqu’un avec qui tu t’entends bien',
  p:`<p>Parle pendant 30 à 60 secondes d’une personne avec qui tu t’entends bien : qui elle est, à quoi elle ressemble, comment elle est, et pourquoi vous vous entendez bien. Utilise au moins une proposition relative et un phrasal verb. Touche « Parler », puis « J’ai fini ».</p>`,
  oral:{modele:'I’d like to talk about my friend Julien. We met at university, in the city where I grew up. He’s tall and slim, with short dark hair and a beard. He’s really funny and very reliable: he’s the person who always helps me when I have a problem. We get on very well because we like the same things, especially football and old films. He looks a bit like his dad, but he takes after his mum: he’s calm and sensible.',
   criteres:['J’ai décrit le physique (taille, cheveux, lunettes…)','J’ai décrit le caractère avec au moins deux adjectifs','J’ai utilisé une relative avec who, which, that ou where','J’ai utilisé un phrasal verb (get on with, grow up, take after…)','J’ai bien soufflé les h de he, her, hair, who']}},

 {kind:'Écriture', h:'Écris un portrait',
  p:'Un site d’échanges linguistiques te demande de présenter une personne importante pour toi (au moins 60 mots) : qui elle est, son physique, son caractère, ce qu’elle fait ou une anecdote. Utilise au moins deux propositions relatives et un phrasal verb.',
  ecrire:{min:60, modele:'The person I want to describe is my aunt Claire. She’s in her fifties, she’s quite tall and she has short grey hair and glasses. She’s a doctor who works in a small hospital in the mountains, where she looks after people from all the villages. She’s generous, hard-working and very funny. When I was a teenager, she was the person who listened to all my problems. I really look up to her.',
   criteres:[{t:'J’ai décrit le physique', re:'\\b(hair|tall|short|slim|glasses|beard|eyes)\\b'},{t:'J’ai décrit le caractère', re:'\\b(friendly|kind|shy|funny|easy-going|hard-working|reliable|sensible|generous|patient|calm)\\b'},{t:'J’ai utilisé une proposition relative (who, which, that, where)', re:'\\b(who|which|that|where)\\b'},{t:'J’ai utilisé un phrasal verb de l’unité', re:'\\b(get|gets|got) on\\b|\\blook(s|ed)? (after|up to)\\b|\\b(grew|grow|grows) up\\b|\\b(bring|brings|brought)( \\w+)? up\\b|\\btak(e|es) after\\b|\\b(fell|fall|falls) out\\b'},'Je n’ai pas répété le pronom après who ou which (pas de « who she »)','J’ai écrit hair au singulier']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>Physique : <i lang="en">tall, short, slim, long/short, curly/straight, fair/dark hair, a beard, glasses, in her thirties</i>. <i>hair</i> reste au singulier : <i lang="en">long curly hair</i>.</li><li>Caractère : <i lang="en">friendly, kind, shy, funny, easy-going, hard-working, reliable</i>. Faux amis : <i>sensible</i> = raisonnable, « sensible » = <i>sensitive</i>.</li><li><b>What does she look like?</b> = le physique. <b>What is she like?</b> = le caractère. <b>look like</b> + nom = ressembler à ; <b>look</b> + adjectif = avoir l’air.</li><li>Relatives : <b>who</b> (personnes), <b>which</b> (choses), <b>that</b> (les deux), <b>where</b> (lieux). Le choix dépend de ce dont on parle, pas de « qui/que ». On ne répète pas le pronom : <s>who he</s>, <s>which … it</s>.</li><li>Le pronom complément peut disparaître : <i lang="en">the photo (that) my mum took</i>. Pour un moment : <i lang="en">the day (that / when) we met</i>, pas <i>where</i>.</li><li>Phrasal verbs : <i lang="en">get on with, look after, grow up, bring up, take after, fall out with, look up to</i>.</li><li>Prononciation : le <i>h</i> se souffle (<i>hair</i> ≠ <i>air</i>), sauf dans <i>hour, honest</i>.</li></ul></div>`},

 {kind:'Mission', h:'Retrouver quelqu’un à la gare',
  p:'Ta collègue Emma te demande d’aller chercher son père à la gare, car elle est coincée au travail. Elle t’a laissé un message vocal. Écoute-le, puis réponds aux questions. Tu peux réécouter à tout moment.',
  audio:'Hi, it’s Emma. Thanks so much for meeting my dad at the station. His train arrives on platform four at half past two. He’s in his sixties, he’s quite tall and he has short grey hair and a beard. He’ll probably wear his old green jacket, the one which has a hole in the sleeve! He’s a bit shy with people he doesn’t know, so you have to say hello first. Oh, and he hates waiting, so please don’t be late!', cache:true,
  parts:[
   {q:'a) Comment reconnaître le père d’Emma&nbsp;?', opts:['Petit, chauve, avec des lunettes et une veste verte','Grand, cheveux longs gris, moustache, veste bleue','Plutôt grand, cheveux courts gris, barbe, vieille veste verte','Taille moyenne, cheveux bruns, barbe, veste verte'], ans:2, hint:'Écoute la taille (<i lang="en">tall</i>), les cheveux (<i lang="en">hair</i>) et la couleur de la veste.', why:'<i lang="en">He’s quite tall and he has short grey hair and a beard</i>, avec sa vieille veste verte trouée à la manche.'},
   {q:'b) Pourquoi dois-tu le saluer le premier&nbsp;?', opts:['Parce qu’il entend mal','Parce qu’il est timide avec les inconnus','Parce qu’il ne parle pas anglais','Parce qu’il est toujours en retard'], ans:1, hint:'Cherche l’adjectif de caractère dans le message.', why:'<i lang="en">He’s a bit shy with people he doesn’t know</i> : il est un peu timide avec les gens qu’il ne connaît pas.'},
   {q:'c) Deux hommes portent une veste verte, mais un seul a une barbe. Dis à ton collègue lequel est le bon : « C’est l’homme qui a une barbe. »', lab:'Ta phrase', txt:['It’s the man who has a beard.',...X(['It is','It’s','He is','He’s','That is','That’s'],['the man','the one'],['who has','that has','who has got','that has got','who’s got','with'],['a beard'])], hint:'Une personne : <i lang="en">who</i>, puis le verbe à la 3e personne.', why:'<i lang="en">It’s the man who has a beard.</i> <i>who</i> remplace <i>he</i>, donc on ne dit pas <s>who he has</s>.'},
   {q:'d) Tu l’as trouvé. Tu écris à Emma : « Il te ressemble beaucoup&nbsp;! »', lab:'Ta phrase', txt:['He looks a lot like you!','He looks just like you!','He really looks like you!','He looks very much like you!','He looks so much like you!','He looks a lot like you'], hint:'« ressembler à » se dit avec <i lang="en">look like</i>.', why:'<i lang="en">He looks a lot like you!</i> (ou <i lang="en">He looks just like you!</i>). <i lang="en">He is like you</i> parlerait plutôt du caractère.'}],
  sol:'<p lang="en">Hi, it’s Emma. Thanks so much for meeting my dad at the station. His train arrives on platform four at half past two. He’s in his sixties, he’s quite tall and he has short grey hair and a beard. He’ll probably wear his old green jacket, the one which has a hole in the sleeve! He’s a bit shy with people he doesn’t know, so you have to say hello first. Oh, and he hates waiting, so please don’t be late!</p><p>Le père d’Emma a une soixantaine d’années, il est plutôt grand, avec des cheveux courts gris, une barbe et une vieille veste verte. Il est timide, donc c’est à toi de le saluer. <i lang="en">It’s the man who has a beard. He looks a lot like you!</i></p>'},

 {kind:'Mission', h:'La nouvelle équipe',
  p:`<p>Tu commences un nouveau travail dans une petite agence de Bristol. Sur le site de l’entreprise, tu lis la page qui présente l’équipe. Lis-la, puis réponds.</p>
<div class="blk" data-t="Meet the team"><p lang="en"><b>Anna</b> is our manager. She started the company ten years ago in a tiny office above a bakery, and that’s why the whole team loves croissants. She’s very hard-working, but she’s also easy-going.<br><b>Ben</b> is the designer who made our logo. He’s tall, with long fair hair, and he always wears headphones. He’s a bit shy, but he’s really funny when you know him.<br><b>Carla</b> looks after our customers. She grew up in Spain and Canada, so she speaks three languages. She’s the person who you should call if you have a problem with a client.<br><b>Dev</b> is our youngest team member. He’s the one who brings the cake on Fridays!</p></div>`,
  parts:[
   {q:'a) Un client mécontent t’appelle. À qui t’adresses-tu&nbsp;?', opts:['Anna','Ben','Carla','Dev'], ans:2, hint:'Cherche <i lang="en">a problem with a client</i>.', why:'<i lang="en">Carla looks after our customers… She’s the person who you should call if you have a problem with a client.</i>'},
   {q:'b) Quelle phrase est vraie&nbsp;?', opts:['Anna est travailleuse et facile à vivre.','Ben est très bavard dès le premier jour.','Carla a grandi en Angleterre.','Dev a dessiné le logo.'], ans:0, hint:'Relis les adjectifs de caractère de chaque personne.', why:'<i lang="en">She’s very hard-working, but she’s also easy-going.</i> Ben est timide, Carla a grandi en Espagne et au Canada, et c’est Ben qui a dessiné le logo.'},
   {q:'c) Décris Ben à un ami avec une relative : « Ben est le designer qui porte toujours des écouteurs. »', lab:'Ta phrase', txt:['Ben is the designer who always wears headphones.',...X(['Ben is','Ben’s'],['the designer'],['who','that'],['always wears headphones','is always wearing headphones','wears headphones all the time'])], hint:'Une personne : <i lang="en">who</i>. Attention au <i>-s</i> du verbe.', why:'<i lang="en">Ben is the designer who always wears headphones.</i> Le verbe de la relative s’accorde avec <i>the designer</i> : <i>wears</i>.'},
   {q:'d) Tu veux savoir comment est Dev (son caractère). Pose la question à Carla.', lab:'Ta question', txt:['What’s Dev like?','What is Dev like?'], hint:'Pour le caractère, la question se termine par <i lang="en">like</i>, sans <i>look</i>.', why:'<i lang="en">What’s Dev like?</i> <i lang="en">What does Dev look like?</i> porterait sur son physique.'},
   {q:'e) Écris en anglais : « Anna est la personne qui a créé l’entreprise. »', lab:'Ta phrase', txt:['Anna is the person who started the company.',...X(['Anna is','Anna’s'],['the person','the woman','the one'],['who','that'],['started','created','founded','set up'],['the company'])], hint:'Une personne : <i lang="en">who</i> ; le verbe est au prétérit.', why:'<i lang="en">Anna is the person who started the company.</i> (<i lang="en">founded</i> ou <i lang="en">set up</i> conviennent aussi.)'}],
  sol:'<p>Pour un problème avec un client, on appelle Carla, qui s’occupe des clients (<i lang="en">looks after our customers</i>). Anna est travailleuse et facile à vivre ; Ben est le designer timide mais drôle. Phrases attendues : <i lang="en">Ben is the designer who always wears headphones. What’s Dev like? Anna is the person who started the company.</i></p>'},
]},

{subj:'en', sem:'a2', id:'en-a2-world', o:12, h:'The world around us', p:'Parler de l’avenir sous condition avec le premier conditionnel, <i lang="en">when, as soon as, unless</i>, discuter d’environnement et relier ses idées avec <i lang="en">because, so, but, although</i>.', steps:[
 {kind:'Écoute', h:'Le train ou la voiture ?',
  p:`<p>À la fin de cette unité, tu sauras parler de l’avenir sous condition (« si…, alors… »), discuter d’environnement et relier tes idées pour argumenter.</p>
<p>Ella et Dan préparent leurs vacances en Cornouailles, au sud-ouest de l’Angleterre, avec leurs deux enfants. <b>Écoute sans lire</b>, puis réponds.</p>
<p><b>Question :</b> à quelle condition prendront-ils le train&nbsp;?</p>`,
  audio:[['Ella','Are we driving to Cornwall again this summer?'],['Dan','I’m not sure. If we take the train, it’ll be better for the environment.'],['Ella','Yes, but it’s expensive for four people.'],['Dan','Not if we book early. If we buy the tickets this week, they’ll be much cheaper.'],['Ella','And the kids will be bored on a five-hour train journey.'],['Dan','Although it’s a long journey, they can read, play games and walk around. In the car, they can’t move at all.'],['Ella','True. And you won’t have to drive for six hours, so you won’t be tired when we arrive.'],['Dan','Exactly! I’ll check the prices as soon as I get home.'],['Ella','OK, but unless the tickets are under three hundred pounds, we’re taking the car.']], cache:true,
  opts:['Si les enfants sont d’accord','Si les billets coûtent moins de 300 livres','Si Dan ne travaille pas cet été','S’il fait beau'], ans:1,
  why:'<i lang="en">Unless the tickets are under three hundred pounds, we’re taking the car</i> : sauf si les billets coûtent moins de 300 livres, ils prendront la voiture. Donc le train seulement si c’est moins de 300 livres.'},

 {kind:'Vocabulaire', h:'L’environnement',
  p:`<p>Voici les mots pour parler d’environnement au quotidien : les problèmes, et les gestes pour les réduire. Touche une ligne pour l’entendre, puis répète-la.</p>`,
  mots:[['the environment','l’environnement','We must protect the environment.'],['climate change','le changement climatique','Climate change is a global problem.'],['pollution','la pollution','There’s a lot of air pollution in big cities.'],['a heatwave','une canicule','There was a heatwave last July.'],['a flood','une inondation','The flood destroyed many homes.'],['to recycle','recycler','We recycle paper, glass and plastic.'],['rubbish (UK) / trash (US)','les déchets, les ordures','Don’t leave your rubbish on the beach.'],['a bin','une poubelle','Put it in the green bin.'],['to throw away','jeter','We throw away too much food.'],['to waste','gaspiller','Don’t waste water!'],['to save energy','économiser l’énergie','Turn off the lights to save energy.'],['to switch off / to turn off','éteindre','Switch off your computer at night.'],['public transport','les transports en commun','I go to work by public transport.'],['renewable energy','les énergies renouvelables','Solar and wind power are renewable energy.'],['to cut down','abattre (des arbres)','They cut down the forest to build a road.'],['a reusable bag','un sac réutilisable','I always take a reusable bag to the supermarket.']],
  note:'<b>rubbish</b>, <b>pollution</b> et <b>energy</b> sont indénombrables : <i lang="en">a lot of rubbish</i>, jamais <s>rubbishes</s>. Orthographe : <i lang="en">environment</i> s’écrit avec un seul <i>n</i> devant le <i>m</i> et sans <i>e</i> au milieu (français : environnement), accent sur <i>vi</i> : en<b>vi</b>ronment.'},

 {kind:'Pratique', h:'À toi : les bons gestes',
  p:'<b>Question :</b> écris en anglais « Nous recyclons le verre et nous éteignons les lumières. »', lab:'Ta phrase',
  txt:['We recycle glass and we switch off the lights.',...X(['We recycle glass and we','We recycle glass and'],['switch off the lights','turn off the lights','switch the lights off','turn the lights off'])],
  why:'<i lang="en">We recycle glass and we switch off (turn off) the lights.</i> Pas d’article devant <i>glass</i> quand on parle de la matière en général.'},

 {kind:'Grammaire', h:'Le 1er conditionnel : if + présent, will',
  p:`<p>Dan dit <i lang="en">If we <b>take</b> the train, it<b>’ll be</b> better for the environment.</i> Il parle d’une situation <b>possible</b> dans l’avenir et de sa conséquence. C’est le premier conditionnel, la structure idéale pour négocier, prévenir ou promettre.</p>
<div class="def"><p><b>If + présent simple, will + verbe de base</b><br><i lang="en">If it rains, we’ll stay at home.</i><br>On peut inverser les deux parties, sans virgule : <i lang="en">We’ll stay at home if it rains.</i></p></div>
<div class="idea"><p>La condition (après <i>if</i>) est au présent, même si elle concerne l’avenir ; la conséquence est au futur avec <i>will</i> ou <i>won’t</i>. À la place de <i>will</i>, on trouve aussi <i>can</i>, <i>must</i> ou un impératif : <i lang="en">If you see Tom, tell him to call me.</i> Bonne nouvelle : le français fait exactement pareil (« s’il pleut, nous resterons »).</p></div>
<div class="ex"><p><i lang="en">If you don’t hurry, you’ll miss the bus.</i><br><i lang="en">If we cut down the forests, many animals will disappear.</i><br><i lang="en">I won’t go to the party if you don’t come with me.</i></p></div>
<div class="warn"><p>Le piège : <b>jamais de <i>will</i> après <i>if</i></b> dans ce sens : <s>If it will rain…</s>. Pas de virgule quand <i>if</i> est au milieu de la phrase. Et n’oublie pas la 3e personne : <i lang="en">If she <b>calls</b>, I’ll tell her.</i></p></div>`,
  audio:'If we take the train, it’ll be better for the environment. If it rains, we’ll stay at home. We’ll stay at home if it rains. If you don’t hurry, you’ll miss the bus.'},

 {kind:'Méthode', h:'Construire une phrase au 1er conditionnel',
  p:`<p><b>Quand :</b> pour une condition réaliste et sa conséquence future : prévenir, négocier, promettre, menacer. <b>Pourquoi ça marche :</b> l’anglais marque l’avenir une seule fois, dans la conséquence ; la condition reste au présent. <b>Comment :</b></p>
<ol><li>Sépare la condition (« si… ») et la conséquence.</li><li>Condition : <b>if + présent simple</b> (<i>-s</i> à la 3e personne, <i>don’t / doesn’t</i> à la négation).</li><li>Conséquence : <b>will / won’t + verbe de base</b>.</li><li>Si <i>if</i> commence la phrase, mets une virgule entre les deux parties.</li></ol>`,
  demo:{enonce:'Traduis : « Si Paul ne prend pas son vélo, il arrivera en retard. »',
   etapes:[{f:'Condition : « si Paul ne prend pas son vélo » ; conséquence : « il arrivera en retard ».',w:'On repère les deux parties.'},
    {f:'<i lang="en">If Paul doesn’t take his bike</i>',w:'Présent simple, 3e personne, négatif : <i>doesn’t take</i>. Pas de <i>will</i> ici.'},
    {f:'<i lang="en">he’ll be late</i>',w:'Futur avec <i>will</i> + base. « Arriver en retard » se dit simplement <i lang="en">be late</i>.'},
    {f:'<i lang="en">If Paul doesn’t take his bike, he’ll be late.</i>',w:'Une virgule après la condition, puisqu’elle vient en premier.'}],
   conclusion:'<i lang="en">If Paul doesn’t take his bike, he’ll be late.</i> ou <i lang="en">Paul will be late if he doesn’t take his bike.</i>'}},

 {kind:'Pratique', h:'À toi : mets les verbes',
  p:'Mets les verbes entre parenthèses à la bonne forme et écris la phrase entière. <b>Question :</b> <i lang="en">If it (rain) tomorrow, we (stay) at home.</i>', lab:'Ta phrase',
  txt:['If it rains tomorrow, we will stay at home.','If it rains tomorrow, we will stay home.'],
  why:'Condition au présent (<i>rains</i>, avec <i>-s</i> car le sujet est <i>it</i>), conséquence avec <i>will</i> : <i lang="en">If it rains tomorrow, we’ll stay at home.</i>'},

 {kind:'Pratique', h:'À toi : une mise en garde',
  p:'Ton ami traîne et le train part dans dix minutes. <b>Question :</b> écris en anglais « Si tu ne te dépêches pas, tu vas rater le train. »', lab:'Ta phrase',
  txt:['If you don’t hurry, you’ll miss the train.',...X(['If you don’t hurry','If you don’t hurry up'],['you will miss the train','you are going to miss the train']),...X(['You will miss the train','You are going to miss the train'],['if you don’t hurry','if you don’t hurry up'])],
  why:'<i lang="en">If you don’t hurry, you’ll miss the train.</i> Négation au présent (<i>don’t hurry</i>), conséquence avec <i>will</i>. « Rater » un train = <i lang="en">miss</i>.'},

 {kind:'Grammaire', h:'When, as soon as, unless',
  p:`<p>Dan promet : <i lang="en">I’ll check the prices <b>as soon as</b> I <b>get</b> home.</i> En français, on dirait « dès que je <b>rentrerai</b> », au futur. En anglais, le verbe reste au <b>présent</b>.</p>
<div class="def"><p>Après <b>when</b> (quand), <b>as soon as</b> (dès que) et <b>unless</b> (à moins que, sauf si), on met le <b>présent simple</b> pour parler du futur, comme après <i>if</i>.<br><i lang="en">I’ll call you when I arrive.</i> = Je t’appellerai quand j’arriverai.<br><b>unless</b> = <i>if … not</i> : <i lang="en">We’ll take the car unless the tickets are cheap.</i> = …si les billets ne sont pas bon marché.</p></div>
<div class="idea"><p><b>if</b> ou <b>when</b> ? <i>if</i> pour ce qui arrivera peut-être, <i>when</i> pour ce qui arrivera sûrement. <i lang="en">If I see Tom, I’ll tell him</i> (je ne suis pas sûr de le voir). <i lang="en">When I see Tom, I’ll tell him</i> (je le vois demain au bureau, c’est certain).</p></div>
<div class="ex"><p><i lang="en">As soon as the film finishes, we’ll go to bed.</i><br><i lang="en">You won’t pass the exam unless you work harder.</i> = …si tu ne travailles pas plus.</p></div>
<div class="warn"><p>C’est le piège numéro un des francophones : <s>when I will arrive</s>, <s>as soon as I will get home</s>. Après <i>when, as soon as, if, unless</i>, pas de <i>will</i>. Et <i>unless</i> contient déjà la négation : <s>unless you don’t work</s> dit le contraire de ce que tu veux dire.</p></div>`,
  audio:'I’ll check the prices as soon as I get home. I’ll call you when I arrive. We’ll take the car unless the tickets are cheap.'},

 {kind:'Pratique', h:'À toi : quand',
  p:'<b>Question :</b> écris en anglais « Je t’appellerai quand j’arriverai. »', lab:'Ta phrase',
  txt:['I’ll call you when I arrive.',...X(['I will call you','I will phone you','I will ring you','I will give you a call'],['when I arrive','when I get there','when I get here']),...X(['When I arrive','When I get there'],['I will call you','I will phone you','I will ring you'])],
  why:'<i lang="en">I’ll call you when I arrive.</i> Après <i>when</i>, le présent : jamais <s>when I will arrive</s>.'},

 {kind:'Pratique', h:'À toi : unless',
  p:'Réécris la phrase avec <i lang="en">unless</i>, sans changer le sens. <b>Question :</b> <i lang="en">If you don’t water the plants, they will die.</i>', lab:'Ta phrase',
  txt:['Unless you water the plants, they will die.','The plants will die unless you water them.'],
  why:'<i>unless</i> = <i>if … not</i> : il remplace <i>if you don’t</i>. <i lang="en">Unless you water the plants, they’ll die.</i> Surtout pas <s>unless you don’t water</s>.'},

 {kind:'Pratique', h:'Remets la promesse dans l’ordre',
  p:'Touche les mots dans le bon ordre. <b>Question :</b> comment dit-on « Je t’enverrai un message dès que je rentrerai à la maison » ?',
  ordre:['I’ll','send you','a message','as soon as','I get','home.'], alt:['As soon as I get home I’ll send you a message'],
  why:'<i lang="en">I’ll send you a message as soon as I get home.</i> Le futur est dans la conséquence (<i>I’ll send</i>), le présent après <i>as soon as</i> (<i>I get</i>).'},

 {kind:'Grammaire', h:'Because, so, but, although : relier ses idées',
  p:`<p>Dans le dialogue, Dan dit <i lang="en"><b>Although</b> it’s a long journey, they can read</i>, et Ella répond <i lang="en">you won’t have to drive, <b>so</b> you won’t be tired</i>. Ces petits mots, les connecteurs, transforment une liste de phrases en un vrai raisonnement.</p>
<div class="def"><p><b>because</b> = parce que (la cause) : <i lang="en">I take the bus because it’s cheaper.</i><br><b>so</b> = donc, alors (la conséquence) : <i lang="en">It’s cheaper, so I take the bus.</i><br><b>but</b> = mais (l’opposition) : <i lang="en">The train is slow, but it’s comfortable.</i><br><b>although</b> = bien que, même si (une concession) : <i lang="en">Although the train is slow, it’s comfortable.</i></p></div>
<div class="idea"><p><i>because</i> et <i>so</i> sont les deux faces d’une même relation : la cause après <i>because</i>, la conséquence après <i>so</i>. <i>but</i> relie deux idées au milieu de la phrase ; <i>although</i> peut se placer au milieu ou ouvrir la phrase. Après <i>although</i>, le verbe est normal : pas de subjonctif comme après « bien que ».</p></div>
<div class="ex"><p><i lang="en">We recycle because we want to protect the environment.</i><br><i lang="en">There was no bus after midnight, so we walked home.</i><br><i lang="en">Although electric cars are expensive, more and more people buy them.</i></p></div>
<div class="warn"><p>Ne mets jamais <i>although</i> et <i>but</i> dans la même phrase : <s>Although it was cold, but we went out</s>. Devant un nom seul, <i>because</i> devient <b>because of</b> : <i lang="en">because of the traffic</i>. Et « car » se traduit par <i>because</i>, pas par <i>car</i>, qui veut dire « voiture »&nbsp;!</p></div>`,
  audio:'I take the bus because it’s cheaper. It’s cheaper, so I take the bus. The train is slow, but it’s comfortable. Although the train is slow, it’s comfortable.'},

 {kind:'Pratique', h:'À toi : although',
  p:'Relie les deux phrases avec <i lang="en">although</i>. <b>Question :</b> <i lang="en">It was raining. We went for a walk.</i>', lab:'Ta phrase',
  txt:['Although it was raining, we went for a walk.','We went for a walk although it was raining.','Even though it was raining, we went for a walk.','We went for a walk even though it was raining.'],
  why:'<i lang="en">Although it was raining, we went for a walk.</i> (ou <i lang="en">We went for a walk although it was raining.</i>) Pas de <i>but</i> en plus.'},

 {kind:'Pratique', h:'À toi : so',
  p:'<b>Question :</b> traduis en anglais « Le bus était en retard, donc j’ai pris un taxi. »', lab:'Ta phrase',
  txt:['The bus was late, so I took a taxi.',...X(['The bus was late so I'],['took','got'],['a taxi','a cab']),'I took a taxi because the bus was late.','I got a taxi because the bus was late.'],
  why:'La conséquence vient après <i>so</i> : <i lang="en">The bus was late, so I took a taxi.</i> On peut aussi inverser avec la cause : <i lang="en">I took a taxi because the bus was late.</i>'},

 {kind:'Prononciation', h:'I’ll, won’t, want : le futur à l’oral',
  p:`<p>À l’oral, <i>will</i> est presque toujours contracté, et on l’entend à peine. Il faut pourtant le reconnaître, et surtout ne pas confondre <i>won’t</i> et <i>want</i>, qui disent presque le contraire.</p>
<div class="def"><ul><li><b>I’ll, you’ll, we’ll</b> : un simple <i>l</i> collé au pronom. <i lang="en">I’ll</i> se dit comme <i lang="en">aisle</i> (« aïl »). <b>it’ll</b> se dit « it’l ».</li><li><b>won’t</b> (= <i>will not</i>) : la voyelle de <i lang="en">no</i>, « wo-ount ». <i lang="en">I won’t go</i> = je n’irai pas.</li><li><b>want</b> : un <i>o</i> court, comme dans <i lang="en">hot</i>. <i lang="en">I want to go</i> = je veux y aller.</li></ul></div>
<div class="warn"><p>Si tu prononces <i>won’t</i> comme <i>want</i>, <i lang="en">I won’t go</i> devient <i lang="en">I want go</i> : ton interlocuteur comprendra l’inverse. Arrondis bien les lèvres sur le « o » de <i>won’t</i>.</p></div>`,
  audio:'I’ll call you. We’ll see. It’ll be fine. I won’t go. I want to go. I won’t go unless you come with me.'},

 {kind:'Écoute', h:'Won’t ou want ?',
  p:'Sophie parle à son collègue Ben de ses trajets. <b>Écoute sans lire</b>, en faisant attention à <i lang="en">won’t</i> et <i lang="en">want</i>. <b>Question :</b> que décide Sophie&nbsp;?',
  audio:[['Sophie','I won’t take the car tomorrow. If I cycle to work, I’ll save money.'],['Ben','And if it rains?'],['Sophie','If it rains, I’ll take the bus. But I want to try!']], cache:true,
  opts:['Elle prendra la voiture demain.','Elle ira au travail à vélo, ou en bus s’il pleut.','Elle prendra la voiture s’il pleut.','Elle restera à la maison s’il pleut.'], ans:1,
  why:'<i lang="en">I won’t take the car tomorrow</i> : elle ne prendra pas la voiture. <i lang="en">If it rains, I’ll take the bus</i> : s’il pleut, elle prendra le bus. <i lang="en">I want to try</i> : elle veut essayer le vélo.'},

 {kind:'Lecture', h:'Cinq petits gestes',
  p:`<p>Lis cet article d’un blog sur l’écologie au quotidien, puis réponds. Tu peux aussi l’écouter.</p>
<div class="blk" data-t="Small changes, big difference"><p lang="en">Many people think that one person can’t do anything about climate change. That’s not true! Here are five easy changes. If everyone makes them, they’ll make a real difference.</p><p lang="en">1. Take a reusable bag when you go shopping. People use a plastic bag for twenty minutes, but it stays in nature for hundreds of years.<br>2. Turn off the lights when you leave a room. You’ll save energy, so your bills will be lower too.<br>3. Eat less meat. You don’t have to become vegetarian, but one or two days without meat each week will help.<br>4. Walk or cycle for short journeys. Although it takes a bit longer, you’ll be healthier and the air will be cleaner.<br>5. Don’t throw away food. Buy only what you need, and cook what is left the next day.</p><p lang="en">Remember: the planet won’t change unless we change first.</p></div>
<p><b>Question :</b> que dit l’article à propos de la viande&nbsp;?</p>`,
  audio:'Many people think that one person can’t do anything about climate change. That’s not true! Here are five easy changes. If everyone makes them, they’ll make a real difference. One. Take a reusable bag when you go shopping. People use a plastic bag for twenty minutes, but it stays in nature for hundreds of years. Two. Turn off the lights when you leave a room. You’ll save energy, so your bills will be lower too. Three. Eat less meat. You don’t have to become vegetarian, but one or two days without meat each week will help. Four. Walk or cycle for short journeys. Although it takes a bit longer, you’ll be healthier and the air will be cleaner. Five. Don’t throw away food. Buy only what you need, and cook what is left the next day. Remember: the planet won’t change unless we change first.',
  opts:['Il faut devenir végétarien.','Un ou deux jours sans viande par semaine, c’est déjà utile.','Il faut arrêter aussi le poisson.','La viande n’a aucun effet sur le climat.'], ans:1,
  why:'<i lang="en">You don’t have to become vegetarian, but one or two days without meat each week will help.</i> Encore <i>don’t have to</i> : pas obligé.'},

 {kind:'Dictée', h:'Dictée : recycler',
  p:'Écoute et écris exactement la phrase. Tu peux réécouter autant que tu veux, et utiliser « Plus lentement ».',
  dictee:'If we recycle more, we will produce less rubbish.',
  why:'Présent après <i lang="en">if</i> (<i>recycle</i>), <i lang="en">will</i> dans la conséquence, et <i lang="en">rubbish</i> avec deux b.'},

 {kind:'Oral', h:'Répète : won’t',
  p:`<p>Écoute la phrase, puis dis-la à voix haute en touchant « Dire la phrase ». Arrondis bien les lèvres sur <i lang="en">won’t</i> pour qu’on ne comprenne pas <i lang="en">want</i>. Rythme : <i lang="en">I <b>won’t</b> <b>go</b> unless you <b>come</b> with me.</i></p>`,
  dire:'I won’t go unless you come with me.',
  note:'Si la reconnaissance vocale écrit <i lang="en">want</i>, allonge le « o » de <i lang="en">won’t</i> et recommence.'},

 {kind:'Oral', h:'Ce que tu feras pour la planète',
  p:`<p>Parle pendant 30 à 60 secondes : qu’est-ce que tu pourrais changer dans ta vie pour l’environnement, et qu’est-ce qui se passera si tu le fais&nbsp;? Utilise au moins deux phrases au premier conditionnel et deux connecteurs. Touche « Parler », puis « J’ai fini ».</p>`,
  oral:{modele:'I think I can do a few things for the environment. If I sell my car, I’ll save a lot of money, so I’ll cycle to work when the weather is good. Although I love meat, I’ll try to eat less of it. And as soon as I move to a bigger flat, I’ll start growing my own vegetables. I won’t change everything at once, but small changes are important because they add up.',
   criteres:['J’ai utilisé au moins deux phrases avec if + présent, will','Je n’ai pas mis will après if, when ou as soon as','J’ai utilisé au moins deux connecteurs (because, so, but, although)','J’ai utilisé du vocabulaire de l’environnement','J’ai bien prononcé won’t (pas want)']}},

 {kind:'Écriture', h:'Une idée pour ta commune',
  p:'Ta commune demande des idées pour une ville plus verte. Écris un message (au moins 60 mots) : propose deux idées, explique leurs conséquences avec le premier conditionnel, utilise au moins trois connecteurs (<i lang="en">because, so, but, although</i>) et une phrase avec <i lang="en">unless</i> ou <i lang="en">as soon as</i>.',
  ecrire:{min:60, modele:'Dear Sir or Madam, I have two ideas for a greener town. First, if the town builds more bike lanes, more people will cycle to work, so there will be less traffic and less pollution. Second, we need more recycling bins in the park, because people often leave their rubbish on the grass. Although these ideas cost money, they will make our town a better place. Nothing will change unless we act now. Best regards, Nina Keller',
   criteres:[{t:'J’ai utilisé le 1er conditionnel (if + présent, will)', re:'\\bif\\b[^.]*\\b(will|won[’\']t)\\b|\\bif\\b[^.]*[’\']ll\\b'},{t:'J’ai utilisé because ou so', re:'\\b(because|so)\\b'},{t:'J’ai utilisé although ou but', re:'\\b(although|but)\\b'},{t:'J’ai utilisé unless, when ou as soon as', re:'\\b(unless|when|as soon as)\\b'},{t:'J’ai utilisé du vocabulaire de l’environnement', re:'\\b(pollution|recycl\\w*|rubbish|energy|environment|climate|public transport|waste)\\b'},'Je n’ai pas mis will après if, when, unless ou as soon as']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>1er conditionnel : <b>if + présent simple, will / won’t + base</b>. <i lang="en">If we take the train, it’ll be cheaper.</i> Virgule seulement si <i>if</i> commence la phrase.</li><li>Après <b>if, when, as soon as, unless</b>, le présent pour parler du futur : <i lang="en">I’ll call you when I arrive</i>, jamais <s>when I will arrive</s>.</li><li><b>if</b> = peut-être ; <b>when</b> = sûrement. <b>unless</b> = <i>if … not</i>, sans autre négation.</li><li>Connecteurs : <b>because</b> (cause), <b>so</b> (conséquence), <b>but</b> (opposition), <b>although</b> (concession, jamais avec <i>but</i>). Devant un nom : <b>because of</b>.</li><li>Environnement : <i lang="en">climate change, pollution, to recycle, rubbish, a bin, to waste, to save energy, to switch off, public transport, renewable energy</i>. <i>rubbish</i> est indénombrable.</li><li>Prononciation : <i>I’ll</i> « aïl », <i>won’t</i> avec le « o » de <i>no</i>, à ne pas confondre avec <i>want</i>.</li></ul></div>`},

 {kind:'Mission', h:'La journée sans voiture',
  p:'Tu habites à Bristol. À la radio locale, tu entends une annonce pour dimanche. Écoute-la, puis réponds aux questions une par une. Tu peux réécouter à tout moment.',
  audio:'Good morning, this is Radio Riverside. Don’t forget: Sunday is car-free day in the city centre. From eight in the morning until six in the evening, cars won’t be allowed in the centre. If you come by bus, the ticket will be free all day. If you need your car, you can park at the station car park and take the shuttle bus. And if the weather is good, there will be a big picnic in Green Park at one o’clock. Bring your own food, and please take your rubbish home with you!', cache:true,
  parts:[
   {q:'a) Pendant quelles heures les voitures sont-elles interdites dans le centre&nbsp;?', opts:['De 6 h à 20 h','De 8 h à 16 h','De 8 h à 18 h','Toute la journée et toute la nuit'], ans:2, hint:'Écoute <i lang="en">From … until …</i>', why:'<i lang="en">From eight in the morning until six in the evening</i> : de 8 heures à 18 heures.'},
   {q:'b) Que se passe-t-il si tu viens en bus&nbsp;?', opts:['Le billet est gratuit toute la journée.','Tu dois réserver ta place.','Le bus s’arrête à la gare.','Tu as droit à un pique-nique gratuit.'], ans:0, hint:'Cherche la phrase qui commence par <i lang="en">If you come by bus</i>.', why:'<i lang="en">If you come by bus, the ticket will be free all day</i> : un premier conditionnel, billet gratuit toute la journée.'},
   {q:'c) Ton ami demande s’il y aura un pique-nique. Réponds en anglais : « S’il fait beau, il y aura un pique-nique à une heure. »', lab:'Ta phrase', txt:['If the weather is good, there will be a picnic at one.',...X(['If the weather is good','If the weather is nice','If it is sunny','If it’s sunny','If it is nice','If it’s nice'],['there will be a picnic'],['at one','at one o’clock','at 1','at 1 p.m.','at 1 pm','at 1pm']),...X(['There will be a picnic'],['at one','at one o’clock','at 1','at 1 p.m.','at 1pm'],['if the weather is good','if the weather is nice','if it is sunny','if it’s sunny'])], hint:'Condition au présent, conséquence avec <i lang="en">there will be</i>.', why:'<i lang="en">If the weather is good, there will be a picnic at one.</i> Pas de <i>will</i> après <i>if</i>.'},
   {q:'d) Écris à ton ami : « Je viendrai en bus, à moins qu’il pleuve. »', lab:'Ta phrase', txt:['I’ll come by bus unless it rains.',...X(['I will come by bus','I will take the bus','I will go by bus'],['unless it rains']),...X(['Unless it rains'],['I will come by bus','I will take the bus','I will go by bus'])], hint:'« à moins que » = <i lang="en">unless</i>, suivi du présent.', why:'<i lang="en">I’ll come by bus unless it rains.</i> Après <i>unless</i>, le présent simple (<i>rains</i>) et aucune autre négation.'}],
  sol:'<p lang="en">Sunday is car-free day in the city centre. From eight in the morning until six in the evening, cars won’t be allowed in the centre. If you come by bus, the ticket will be free all day. If you need your car, you can park at the station car park and take the shuttle bus. And if the weather is good, there will be a big picnic in Green Park at one o’clock.</p><p>Voitures interdites de 8 h à 18 h, bus gratuit, pique-nique à 13 h s’il fait beau. Réponses : <i lang="en">If the weather is good, there will be a picnic at one. I’ll come by bus unless it rains.</i></p>'},

 {kind:'Mission', h:'Un bureau plus vert',
  p:`<p>Tu travailles dans une entreprise à Londres. La responsable du bureau envoie ce message à toute l’équipe. Lis-le, puis réponds.</p>
<div class="blk" data-t="E-mail"><p lang="en">Hi everyone,<br>From next Monday, our office is going green! Here are the changes.<br>– The coffee machine won’t give plastic cups any more, so please bring your own mug. If you forget it, you can buy one at reception for £3.<br>– There will be recycling bins on every floor. Paper goes in the blue bin and plastic in the yellow one.<br>– The heating will switch off automatically at 7 p.m. If you work late, you’ll need a jumper!<br>– Although we know it isn’t always easy, we’d like everyone to come to work by public transport or by bike at least once a week. Staff who cycle to work will get a free breakfast on Fridays.<br>If you have any other ideas, please tell me as soon as possible.<br>Thanks, Linda</p></div>`,
  parts:[
   {q:'a) Tu as oublié ta tasse. Que peux-tu faire&nbsp;?', opts:['Prendre un gobelet en plastique à la machine','En acheter une à l’accueil pour 3 livres','Utiliser la tasse de Linda','Rien, le café est interdit'], ans:1, hint:'Cherche la phrase qui commence par <i lang="en">If you forget it</i>.', why:'<i lang="en">If you forget it, you can buy one at reception for £3.</i> La machine ne donnera plus de gobelets en plastique.'},
   {q:'b) Dans quelle poubelle mets-tu une bouteille en plastique&nbsp;?', opts:['La bleue','La verte','La poubelle normale','La jaune'], ans:3, hint:'<i lang="en">the yellow one</i> = la jaune.', why:'<i lang="en">Paper goes in the blue bin and plastic in the yellow one.</i>'},
   {q:'c) Écris en anglais : « Si je viens au travail à vélo, j’aurai un petit-déjeuner gratuit le vendredi. »', lab:'Ta phrase', txt:['If I cycle to work, I’ll get a free breakfast on Fridays.',...X(['If I cycle to work','If I come to work by bike','If I ride my bike to work','If I go to work by bike','If I come to work by bicycle'],['I will get','I will have'],['a free breakfast'],['on Friday','on Fridays'])], hint:'Condition au présent, conséquence avec <i lang="en">will</i>. « Avoir » un avantage se dit souvent <i lang="en">get</i>.', why:'<i lang="en">If I cycle to work, I’ll get a free breakfast on Fridays.</i> Le présent après <i>if</i>, <i>will</i> dans la conséquence.'},
   {q:'d) Réponds à Linda avec une idée : « Nous devrions éteindre les ordinateurs le soir, parce que ça économise de l’énergie. »', lab:'Ta phrase', txt:['We should switch off the computers in the evening because it saves energy.',...X(['We should switch off','We should turn off'],['the computers','our computers'],['in the evening','at night'],['because it saves energy','because that saves energy','because this saves energy']),...X(['We should switch','We should turn'],['the computers','our computers'],['off'],['in the evening','at night'],['because it saves energy','because that saves energy'])], hint:'<i lang="en">should</i> pour un conseil, <i lang="en">because</i> pour la cause.', why:'<i lang="en">We should switch off the computers in the evening because it saves energy.</i> <i>because</i> introduit la cause ; <i>saves</i> prend un <i>-s</i> (sujet <i>it</i>).'}],
  sol:'<p>Sans tasse, on en achète une à l’accueil pour 3 livres ; le plastique va dans la poubelle jaune. Phrases attendues : <i lang="en">If I cycle to work, I’ll get a free breakfast on Fridays.</i> et <i lang="en">We should switch off the computers in the evening because it saves energy.</i> Dans le message de Linda, repère aussi <i lang="en">so please bring your own mug</i> (conséquence) et <i lang="en">Although we know it isn’t always easy</i> (concession).</p>'},
]},
);
})();
